use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    let jobs = input["jobs"].as_array().unwrap();
    let quantum = input["quantum"].as_u64().unwrap() as i64;
    let mut jobs = jobs.iter().enumerate().map(|(i, &work)| (i as i64, work)).collect::<Vec<_>>();
    let mut completed = Vec::new();
    let mut time = 0;

    while !jobs.is_empty() {
        for i in 0..jobs.len() {
            let (index, work) = &mut jobs[i];
            if *work > 0 {
                let work_to_do = quantum.min(*work);
                *work -= work_to_do;
                time += work_to_do;
                if *work == 0 {
                    completed.push(*index);
                }
            }
        }
    }

    json!(completed)
}
